```java
    @Test
    void aCancellationDuringTheHostKeyScanKeepsTheOperationTerminalAndSingleAudited() throws Exception {
        var events = new CopyOnWriteArrayList<Map<String, String>>();
        var runner = new FakeRunner();
        runner.scanOutput = SCANNED_KEY;
        runner.holdScan();
        try (var orchestration = orchestration(runner, Duration.ofSeconds(30), Duration.ofSeconds(5), events)) {
            RemoteOrchestration.Snapshot submitted = orchestration.submit(connect("deploy-alias", "c-1"));
            assertTrue(runner.awaitScanStarted(), "the fingerprint scan must be in flight");

            RemoteOrchestration.Snapshot cancelled = orchestration.cancel(submitted.operationId());
            assertEquals(RemoteOrchestration.State.CANCELLED, cancelled.state());
            assertEquals(1, events.size(), "cancelling a running operation writes exactly one audit event");

            // The scan result now lands on an operation that is already terminal.
            runner.releaseScan();

            var observedStates = new LinkedHashSet<RemoteOrchestration.State>();
            var observedSteps = new LinkedHashSet<List<String>>();
            int audited = 0;
            long deadline = System.nanoTime() + Duration.ofSeconds(1).toNanos();
            while (System.nanoTime() < deadline) {
                RemoteOrchestration.Snapshot sample = orchestration.get(submitted.operationId());
                observedStates.add(sample.state());
                observedSteps.add(sample.steps());
                audited = Math.max(audited, events.size());
                sleep(2);
            }

            assertEquals(java.util.Set.of(RemoteOrchestration.State.CANCELLED), observedStates,
                    "a terminal state must not regress when the scan returns");
            assertEquals(java.util.Set.of(cancelled.steps()), observedSteps,
                    "a late phase must not be recorded after the terminal state");
            assertEquals(1, audited, "one operation produces exactly one terminal audit event");
            assertFalse(runner.connected(), "a cancelled operation must not open an authenticated session");
        }
    }
```

